const inputs=transfers.filter(x=>same(x.a.to,pool)&&x.a.value===out[0]),outputs=transfers.filter(x=>same(x.a.from,pool)&&x.a.value===-out[1]);assert.equal(inputs.length,1);assert.equal(outputs.length,1);
