function reject(name,mutate,pattern){const a={receipt:structuredClone(receipt),trace:structuredClone(trace)};mutate(a,getSwap(a.trace));let error=null;try{originalLeg("kyber2",pool,descriptor,a.receipt,a.trace);}catch(e){error=e;}assert(error,name+" was incorrectly accepted");if(pattern)assert.match(String(error.message),pattern);cases.push({name,status:"rejected",message:error.message});}
