for(const [name,value] of [["false",word(0n)],["noncanonical bool",word(2n)],["short hex","0x01"],["not hex","malformed"],["extra byte",word(1n)+"00"]])reject("child returndata "+name,(_,s)=>s.calls[0].output=value,returnGate);
reject("malformed transfer calldata",(_,s)=>s.calls[0].input="0xa9059cbb");
reject("swap sender/event mismatch",(_,s)=>s.from=pool);
