const t=structuredClone(trace);if(value===undefined)delete getSwap(t).calls[0].output;else getSwap(t).calls[0].output=value;const got=originalLeg("kyber2",pool,descriptor,receipt,t);assert.equal(got.amountOut,1340519n);positives.push({returndata:name,amountOut:String(got.amountOut)});}
