const fs = require('node:fs');
const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const base = '/Users/eunice/src/MEV/logs/four-family-coverage-20261012.tO076Z';
const sha = value => crypto.createHash('sha256').update(value).digest('hex');
const raw = fs.readFileSync(base + '/kyber2-dual-attempt02.json');
const failedRaw = fs.readFileSync(base + '/kyber2-dual-attempt01.json');
assert.equal(sha(raw), 'cdbb1f96bf77b1b98e40ca81dc39134c20526231def5b34d1d4038569bab660c');
assert.equal(sha(failedRaw), '974469af837c659a8bf5eda08cbbc1a7587ceaab15f68a32dfb966b98137b770');
const r = JSON.parse(raw), failed = JSON.parse(failedRaw);
const lower = v => v.toLowerCase(), same = (a,b) => lower(a) === lower(b);
const stringify = value => JSON.stringify(value, (_k,v) => typeof v === 'bigint' ? String(v) : v, 2);
const originalHashes = {};
for (const field of ['receipt', 'trace']) {
  const h = sha(JSON.stringify(r.original[field], null, 2));
  assert.equal(h, r.original[field+'Sha256']);
  assert.equal(h, sha(JSON.stringify(failed.original[field], null, 2)));
  originalHashes[field] = h;
}
assert.equal(r.code.evidenceSha256, '3fd31c3aa92722626e620a1b33dc6fdd1106551d6bee8636bf62c818f165ee6d');
assert.equal(r.result, 'pass-with-spliced-reference'); assert.deepEqual(r.errors, []);
assert.deepEqual(r.source, {number:26030898, hash:'0x05d0271146d5fbe99d5a6c525520896d869f7da473de5e89bfc259b25a01fe3e',generation:26030898});
assert.equal(r.samples.length, 2);
const pool = '0x952ffc4c47d66b454a8181f5c68b6248e18b66ec';
const actor = r.actors.executor;
const byPath = (node,path) => path.reduce((n,i) => n.calls[i], node);
const originalSwap = byPath(r.original.trace, [0,1,0,1,0,1,0,1,12,0]);
assert(same(originalSwap.to, pool));
const swapSelector = originalSwap.input.slice(0,10);
const successful = (node, path=[], result=[]) => {
  if (!node || node.error || node.revertReason) return result;
  result.push({node,path});
  for (const [i,child] of (node.calls||[]).entries()) successful(child,[...path,i],result);
  return result;
};
const account = (diff,side,address) => Object.entries(diff[side]).find(([k]) => same(k,address))?.[1] || {};
const storage = (diff,side,token,slot) => {
  const entry = Object.entries(account(diff,side,token).storage||{}).find(([k]) => BigInt(k) === BigInt(slot));
  return entry ? BigInt(entry[1]) : undefined;
};
const observe = (diff,token,slot,initial) => {
  assert(diff.pre && diff.post);
  const pre = storage(diff,'pre',token,slot), post = storage(diff,'post',token,slot);
  const before = pre ?? (post === undefined ? initial : 0n);
  const after = post ?? (pre === undefined ? initial : 0n);
  assert.equal(before, initial);
  return {before,after,delta:after-before};
};
const word = (input,index) => '0x'+input.slice(10+64*index,10+64*(index+1));
const transfer = (entry,from,token,to,amount) => {
  const n=entry.node;
  return n.type==='CALL' && same(n.from,from) && same(n.to,token) &&
    n.input?.startsWith('0xa9059cbb') && n.input.length>=138 &&
    same('0x'+word(n.input,0).slice(-40),to) && BigInt(word(n.input,1))===amount;
};
const outputs = [];
let executions=0, noInputControls=0;
for (const s of r.samples) {
  assert(same(s.instance,pool));
  assert.deepEqual(s.productionReferenceGate,{status:'unmet',reason:'missing-valuation'});
  assert.deepEqual({exactCalls:s.runtimeConstruction.exactCalls,quotedCalls:s.runtimeConstruction.quotedCalls,rpcCalls:s.runtimeConstruction.rpcCalls,quotedFallback:s.runtimeConstruction.quotedFallback},
    {exactCalls:0,quotedCalls:0,rpcCalls:0,quotedFallback:false});
  for (const t of s.trials) {
    assert.equal(t.status,'pass'); assert.equal(t.executions.length,4);
    assert.equal(new Set(t.executions.map(e=>e.encoding+':'+e.inventoryControl)).size,4);
    const amountIn=BigInt(t.amountIn), out=BigInt(t.quote.amountOut), details=[];
    for (const e of t.executions) {
      assert.equal(e.status,'pass'); assert.deepEqual(e.source,r.source);
      assert.equal(e.executorCodeHash,r.runtimeCode.keccak256);
      assert(same(e.transaction.from,r.actors.owner) && same(e.transaction.to,actor));
      assert(same(e.trace.from,e.transaction.from) && same(e.trace.to,e.transaction.to));
      assert.equal(e.trace.input,e.transaction.data); assert(!e.trace.error && !e.trace.revertReason);
      const slots=[s.tokenIn,s.tokenOut].map(token=>{
        const matches=r.balanceSlotProofs.filter(p=>same(p.token,token)&&same(p.actor,actor));
        assert.equal(matches.length,1); return matches[0].slot;
      });
      const balances=[s.tokenIn,s.tokenOut].map((token,i)=>observe(e.diff,token,slots[i],BigInt(e.initial[i])));
      assert.equal(balances[0].delta,-amountIn); assert.equal(balances[1].delta,out);
      assert.deepEqual(JSON.parse(stringify(balances)),e.balances); assert.equal(e.signedDelta,'0');
      const nativeBefore=account(e.diff,'pre',actor).balance, nativeAfter=account(e.diff,'post',actor).balance;
      const nb=nativeBefore === undefined ? (nativeAfter === undefined ? 17n : 0n) : BigInt(nativeBefore);
      const na=nativeAfter === undefined ? (nativeBefore === undefined ? 17n : 0n) : BigInt(nativeAfter);
      assert.equal(nb,17n); assert.equal(na,17n);
      assert.deepEqual(e.nativeInventory,{before:'17',after:'17',delta:'0'});
      const swaps=successful(e.trace).filter(({node:n})=>n.type==='CALL'&&same(n.to,pool)&&n.input?.startsWith(swapSelector));
      assert.equal(swaps.length,1);
      const descendants=successful(swaps[0].node,swaps[0].path);
      const paid=descendants.filter(c=>transfer(c,pool,s.tokenOut,actor,out));
      const debited=descendants.filter(c=>transfer(c,actor,s.tokenIn,pool,amountIn));
      assert.equal(paid.length,1); assert.equal(debited.length,1);
      for (const p of [...paid,...debited]) {
        const v=p.node.output??'0x';
        assert(v==='0x'||(/^0x[0-9a-fA-F]{64}$/.test(v)&&BigInt(v)===1n));
      }
      if (e.inventoryControl) {
        assert.equal(e.initial[1],'1000000000000000000000000');
        assert(e.noInput.error || e.noInput.revertReason);
        assert(same(e.noInput.from,e.transaction.from)&&same(e.noInput.to,e.transaction.to));
        assert.equal(e.noInput.input,e.transaction.data);
        noInputControls++;
      }
      executions++;
      details.push({encoding:e.encoding,inventoryControl:e.inventoryControl,debit:balances[0].delta.toString(),credit:balances[1].delta.toString(),outputPath:paid[0].path,inputPath:debited[0].path,nativeUnchanged:true,noInputReverted:e.inventoryControl?true:null});
    }
    if(t.originalTxComparison?.signedDelta!==null&&t.originalTxComparison?.signedDelta!==undefined)
      assert.equal(out-BigInt(t.originalTxComparison.originalAmountOut),BigInt(t.originalTxComparison.signedDelta));
    outputs.push({tokenIn:s.tokenIn,tokenOut:s.tokenOut,label:t.label,amountIn:t.amountIn,amountOut:t.quote.amountOut,originalTxSignedDelta:t.originalTxComparison?.signedDelta??null,executions:details});
  }
}
assert.equal(executions,16); assert.equal(noInputControls,8);
console.log(stringify({kind:'offline_saved_attempt02_selected_receipt_crosscheck',artifactSha256:sha(raw),originalFailureSha256:sha(failedRaw),originalHashes,swapSelector,executionsVerified:executions,noInputControlsVerified:noInputControls,traceAndTransactionBound:true,sourceBound:true,allTokenBalanceDeltasRecomputed:true,allPoolOutputAndActorInputCallsMatched:true,nativeInventoryUnchanged:true,results:outputs,naturalProductionReference:'unmet/missing-valuation; spliced amountIn only',originalPreCallParity:'not verified; historical input at N-end differs by -29 units',newRpcCalls:0,newEvmTrials:0}));
